import{_ as e,o,c as s,a4 as t}from"./chunks/framework.BRzJ4ijD.js";const _=JSON.parse('{"title":"优化","description":"","frontmatter":{},"headers":[],"relativePath":"compilers/opt/index.md","filePath":"compilers/opt/README.md","lastUpdated":1788475713000}'),i={name:"compilers/opt/index.md"};function n(r,a,l,p,d,c){return o(),s("div",null,[...a[0]||(a[0]=[t('<h1 id="优化" tabindex="-1">优化 <a class="header-anchor" href="#优化" aria-label="Permalink to &quot;优化&quot;">​</a></h1><p>机器无关优化在 IR 上做，机器相关优化在指令选择后做。现代编译器把这两个阶段都用 SSA 形式表达——LLVM 在 IR 上做 Inline、GVN、DCE、LICM、向量化；HotSpot C2 用 Sea-of-Nodes 做 Ideal Graph 优化；Cranelift 用 CLIF IR。优化的本质是<strong>用更便宜的指令序列产生语义等价的程序</strong>，证明等价性靠数据流方程 + SSA 形式。</p><p>优化 pass 不是孤立的，而是<strong>迭代流水线</strong>：一个 pass 可能产生另一个 pass 的机会（Inline 后才能做 Constant Propagation，CP 后才能做 DCE，DCE 后才能做 Inline 的下一轮），所以编译器用 Fixed-point iteration 或 Worklist algorithm 反复跑到不动点或达到预算上限。LLVM 默认 <code>O2</code> 跑 ~60 个 pass，<code>O3</code> 跑 ~80 个，每个 pass 都有 cost model 决定是否值得做。</p><ul><li><a href="./basic">常量折叠、复写传播、死代码消除</a></li><li><a href="./loop">循环优化、向量化、strength reduction</a></li><li><a href="./inline">Inline / IPA / escape analysis</a></li></ul><h2 id="优化的代价模型" tabindex="-1">优化的代价模型 <a class="header-anchor" href="#优化的代价模型" aria-label="Permalink to &quot;优化的代价模型&quot;">​</a></h2><p>一条 pass 是否值得运行，编译器用<strong>三件事</strong>评估：</p><ol><li><strong>编译时间成本</strong>：pass 运行时间。Release 编译慢，但 debug 编译用 <code>-O0</code> 跳过所有优化 pass。</li><li><strong>代码体积成本</strong>：Inline 让代码变大，可能 i-cache miss 反而变慢。</li><li><strong>运行时收益</strong>：profile-guided optimization (PGO) 用真实运行 profile 决定哪些路径热，决定 inline 阈值、块布局、分支预测 hint。</li></ol><p>LLVM 的 <code>opt</code> 把 pass 分两类：module pass 跨函数分析（Inline、LTO），function pass 单函数分析（DCE、GVN），loop pass 单循环分析（LICM）。pass manager 决定调度——分析 pass 缓存结果，转换 pass 修改 IR，依赖关系用Invalidation 传播。</p><hr><p>下一节 → <a href="./basic">常量折叠、复写传播、死代码消除</a></p>',10)])])}const m=e(i,[["render",n]]);export{_ as __pageData,m as default};
